def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re
    import sys

    sys.setrecursionlimit(100000)

    DIV0 = "#DIV/0!"
    CYCLE = "#CYCLE!"
    CELL_RE = re.compile(r"[A-Z][1-9][0-9]?")
    FUNC_NAMES = {"SUM", "MIN", "MAX", "IF"}
    CMP_OPS = {"=", "<>", "<", "<=", ">", ">="}

    def tokenize(s: str):
        toks = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == " ":
                i += 1
                continue
            if c.isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                toks.append(("num", int(s[i:j])))
                i = j
                continue
            if c.isalpha():
                j = i
                while j < n and s[j].isalnum():
                    j += 1
                text = s[i:j]
                i = j
                if CELL_RE.fullmatch(text):
                    toks.append(("cell", text))
                elif text in FUNC_NAMES:
                    toks.append(("func", text))
                else:
                    raise ValueError("bad name")
                continue
            two = s[i:i + 2]
            if two in ("<=", ">=", "<>"):
                toks.append(("op", two))
                i += 2
                continue
            if c in "+-*/(),:=<>":
                toks.append(("op", c))
                i += 1
                continue
            raise ValueError("bad character")
        toks.append(("end", None))
        return toks

    def parse_formula(s: str):
        toks = tokenize(s)
        pos = [0]

        def peek(k=0):
            idx = pos[0] + k
            return toks[idx] if idx < len(toks) else ("end", None)

        def take():
            t = peek()
            pos[0] += 1
            return t

        def expect(val):
            t = take()
            if t != ("op", val):
                raise ValueError("expected " + val)

        def parse_expr():
            node = parse_term()
            while peek()[0] == "op" and peek()[1] in ("+", "-"):
                op = take()[1]
                node = ("bin", op, node, parse_term())
            return node

        def parse_term():
            node = parse_factor()
            while peek()[0] == "op" and peek()[1] in ("*", "/"):
                op = take()[1]
                node = ("bin", op, node, parse_factor())
            return node

        def parse_factor():
            if peek() == ("op", "-"):
                take()
                return ("neg", parse_factor())
            return parse_atom()

        def parse_atom():
            t = take()
            if t[0] == "num":
                return ("num", t[1])
            if t[0] == "cell":
                return ("cell", t[1])
            if t == ("op", "("):
                node = parse_expr()
                expect(")")
                return node
            if t[0] == "func":
                name = t[1]
                expect("(")
                if name == "IF":
                    node = parse_if_args()
                else:
                    node = ("call", name, parse_agg_args())
                expect(")")
                return node
            raise ValueError("bad atom")

        def parse_agg_arg():
            if peek()[0] == "cell" and peek(1) == ("op", ":") and peek(2)[0] == "cell":
                c1 = take()[1]
                take()
                c2 = take()[1]
                return ("range", c1, c2)
            return parse_expr()

        def parse_agg_args():
            args = [parse_agg_arg()]
            while peek() == ("op", ","):
                take()
                args.append(parse_agg_arg())
            return args

        def parse_if_args():
            left = parse_expr()
            t = take()
            if not (t[0] == "op" and t[1] in CMP_OPS):
                raise ValueError("bad comparison")
            op = t[1]
            right = parse_expr()
            expect(",")
            then = parse_expr()
            expect(",")
            other = parse_expr()
            return ("if", left, op, right, then, other)

        node = parse_expr()
        if peek()[0] != "end":
            raise ValueError("trailing tokens")
        return node

    values = {}
    active = set()

    def is_err(v):
        return isinstance(v, str)

    def cell_parts(name):
        return ord(name[0]) - 65, int(name[1:])

    def trunc_div(a, b):
        q = abs(a) // abs(b)
        return -q if (a < 0) != (b < 0) else q

    def compare(op, a, b):
        if op == "=":
            return a == b
        if op == "<>":
            return a != b
        if op == "<":
            return a < b
        if op == "<=":
            return a <= b
        if op == ">":
            return a > b
        return a >= b

    def eval_cell(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in active:
            return CYCLE
        active.add(name)
        content = cells[name]
        if content.startswith("="):
            v = eval_ast(parse_formula(content[1:]))
        else:
            v = int(content)
        active.discard(name)
        values[name] = v
        return v

    def eval_ast(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "cell":
            return eval_cell(node[1])
        if kind == "neg":
            v = eval_ast(node[1])
            return v if is_err(v) else -v
        if kind == "bin":
            _, op, l, r = node
            lv = eval_ast(l)
            if is_err(lv):
                return lv
            rv = eval_ast(r)
            if is_err(rv):
                return rv
            if op == "+":
                return lv + rv
            if op == "-":
                return lv - rv
            if op == "*":
                return lv * rv
            if rv == 0:
                return DIV0
            return trunc_div(lv, rv)
        if kind == "call":
            return eval_call(node)
        if kind == "if":
            _, l, op, r, t, e = node
            lv = eval_ast(l)
            if is_err(lv):
                return lv
            rv = eval_ast(r)
            if is_err(rv):
                return rv
            return eval_ast(t if compare(op, lv, rv) else e)
        raise ValueError("bad node")

    def eval_call(node):
        _, name, args = node
        vals = []
        for arg in args:
            if arg[0] == "range":
                _, n1, n2 = arg
                c1, r1 = cell_parts(n1)
                c2, r2 = cell_parts(n2)
                for r in range(min(r1, r2), max(r1, r2) + 1):
                    for c in range(min(c1, c2), max(c1, c2) + 1):
                        nm = chr(65 + c) + str(r)
                        if nm in cells:
                            v = eval_cell(nm)
                            if is_err(v):
                                return v
                            vals.append(v)
            else:
                v = eval_ast(arg)
                if is_err(v):
                    return v
                vals.append(v)
        if name == "SUM":
            return sum(vals)
        if name == "MIN":
            return min(vals) if vals else 0
        return max(vals) if vals else 0

    return {name: eval_cell(name) for name in cells}
